-- Programa de niilismo: duas unidades e quatro aulas com vídeo em português.
-- Preserva edições administrativas se o programa já tiver sido cadastrado.
begin;
insert into public.content_programs
  (id, title, tagline, description, topic, level, weeks, outcomes, curriculum, published)
select id, title, tagline, description, topic, level, weeks, outcomes, curriculum, published
from jsonb_to_recordset($nihilism$[{"id":"niilismo_sentido","title":"Niilismo: riscos e reconstrução de sentido","tagline":"Questione o sentido sem abandonar o cuidado e a responsabilidade.","description":"Entenda o niilismo e os riscos de transformar a ideia de que nada importa em apatia ou indiferença. Reflita sobre valores, consequências e compromissos possíveis no cotidiano.","weeks":2,"topic":"Filosofia","level":"iniciante","outcomes":["Compreender o niilismo existencial","Examinar os riscos da apatia e da indiferença","Questionar valores com responsabilidade","Construir compromissos que façam sentido"],"curriculum":[{"id":"compreender_niilismo","title":"Entender o niilismo e seus riscos","lessons":[{"id":"niilismo_significado","title":"O que significa dizer que nada importa?","body":"Niilismo é um nome usado para posições e problemas filosóficos diferentes. Neste programa, o foco é o niilismo existencial: o questionamento de um sentido ou propósito objetivo dado de antemão à vida. Isso não resume todas as formas de niilismo.\n\nNietzsche investigou a crise dos valores tradicionais e a possibilidade de criar valores. Sua reflexão vai além de repetir que nada vale a pena. Questionar uma certeza pode abrir uma investigação; concluir que nenhuma escolha merece cuidado é um passo adicional que precisa ser examinado.","practice":"Assista ao vídeo e anote uma ideia que você entendeu e uma pergunta que ainda tem. Diferencie uma dúvida sobre sentido de uma conclusão sobre como agir.","minutes":3,"habit_key":null,"media":{"title":"O Niilismo EXPLICADO","author":"Ciência Todo Dia • Pedro Loos","summary":"Uma introdução ao niilismo, à crítica de Nietzsche e às respostas à perda de sentido. Assista para refletir sobre a diferença entre questionar valores e abandonar qualquer compromisso com a vida cotidiana.","url":"https://www.youtube.com/watch?v=2t1vB8TeUUc","kind":"video","thumbnail_url":"https://i.ytimg.com/vi/2t1vB8TeUUc/hqdefault.jpg"}},{"id":"niilismo_riscos","title":"Quando o vazio vira uma justificativa para desistir","body":"O risco abordado aqui aparece quando a frase “nada importa” passa a justificar abandonar compromissos, desprezar vínculos ou tratar qualquer esforço como inútil. Uma dúvida filosófica pode se tornar uma conclusão rígida que encerra a reflexão antes de examinar alternativas.\n\nImagine deixar de conversar com alguém importante porque nenhuma relação durará para sempre. A duração limitada não demonstra que essa conversa é sem valor. Em vez de assumir que tudo é indiferente, pergunte o que sua escolha muda para você e para as pessoas envolvidas. Essa é uma aplicação prática para reflexão, não uma consequência inevitável de estudar niilismo.","practice":"Escolha uma situação em que pensou “tanto faz”. Descreva duas ações possíveis e as consequências concretas de cada uma.","minutes":3,"habit_key":null,"media":{"title":"O Niilismo EXPLICADO","author":"Ciência Todo Dia • Pedro Loos","summary":"Uma introdução ao niilismo, à crítica de Nietzsche e às respostas à perda de sentido. Assista para refletir sobre a diferença entre questionar valores e abandonar qualquer compromisso com a vida cotidiana.","url":"https://www.youtube.com/watch?v=2t1vB8TeUUc","kind":"video","thumbnail_url":"https://i.ytimg.com/vi/2t1vB8TeUUc/hqdefault.jpg"}}]},{"id":"reconstruir_sentido","title":"Valores, vínculos e responsabilidade","lessons":[{"id":"niilismo_responsabilidade","title":"Questionar valores não elimina consequências","body":"Não encontrar um propósito universal não prova, por si só, que todas as ações sejam equivalentes. Pessoas continuam sendo afetadas por promessas, escolhas e omissões. É possível discutir de onde vêm os valores e, ao mesmo tempo, considerar cuidado, reciprocidade e responsabilidade nas decisões.\n\nUma forma de examinar uma escolha é perguntar: quem será afetado, que dano posso evitar e que razões consigo explicar aos envolvidos? Você não precisa resolver todas as questões da filosofia para reconhecer um compromisso concreto. Essa proposta de reflexão não pretende ser a única resposta possível ao niilismo.","practice":"Relembre um compromisso com outra pessoa. Escreva por que cumpri-lo ou renegociá-lo importa, mesmo sem uma certeza sobre o sentido da vida.","minutes":3,"habit_key":null,"media":{"title":"O Niilismo EXPLICADO","author":"Ciência Todo Dia • Pedro Loos","summary":"Uma introdução ao niilismo, à crítica de Nietzsche e às respostas à perda de sentido. Assista para refletir sobre a diferença entre questionar valores e abandonar qualquer compromisso com a vida cotidiana.","url":"https://www.youtube.com/watch?v=2t1vB8TeUUc","kind":"video","thumbnail_url":"https://i.ytimg.com/vi/2t1vB8TeUUc/hqdefault.jpg"}},{"id":"niilismo_compromissos","title":"Experimente um sentido em ações pequenas","body":"Uma resposta possível à perda de referências é investigar quais atividades e relações você considera dignas de cuidado. Aprender algo, criar, colaborar ou estar presente em uma conversa são possibilidades para explorar; nenhuma precisa valer como resposta para todas as pessoas.\n\nEscolha um compromisso pequeno, explique sua razão e observe a experiência. Depois revise: o que teve valor, o que não fez sentido e o que deseja mudar? Construir uma orientação não exige fingir certeza nem transformar produtividade em medida de valor pessoal. A proposta é manter a reflexão aberta enquanto participa da vida cotidiana.","practice":"Reserve um momento para ler sobre uma pergunta que importa para você. Registre um aprendizado e uma ação possível para os próximos dias.","minutes":3,"habit_key":"read","media":{"title":"O Niilismo EXPLICADO","author":"Ciência Todo Dia • Pedro Loos","summary":"Uma introdução ao niilismo, à crítica de Nietzsche e às respostas à perda de sentido. Assista para refletir sobre a diferença entre questionar valores e abandonar qualquer compromisso com a vida cotidiana.","url":"https://www.youtube.com/watch?v=2t1vB8TeUUc","kind":"video","thumbnail_url":"https://i.ytimg.com/vi/2t1vB8TeUUc/hqdefault.jpg"}}]}],"published":true}]$nihilism$::jsonb) as p(
  id text, title text, tagline text, description text, topic text, level text,
  weeks integer, outcomes jsonb, curriculum jsonb, published boolean
)
on conflict (id) do nothing;
commit;
